// ============================================================================
//  SKYBLOCK ECONOMY - CONFIG
//  Everything you'll want to tweak is in here.
//
//  Item buy/sell prices for every vanilla item are in prices.js, generated by
//  tools/generate_prices.py so that buying items, crafting them and selling
//  the result can never make a profit. To change a single price use
//  PRICE_OVERRIDES below (careful: overrides skip that anti-profit check).
// ============================================================================

export const CONFIG = {
  // Scoreboard objective that stores everyone's money.
  // Admins can also use:  /scoreboard players add <player> money 1000
  objective: "money",
  objectiveDisplay: "§aMoney",
  currency: "$",

  startingBalance: 500,
  maxBalance: 2000000000, // scoreboard limit is ~2.1 billion

  adminTag: "admin", // /tag <player> add admin  -> shows the Admin tile

  compass: {
    giveOnJoin: true, // make sure every player has the compass when they spawn
    slot: 8, // hotbar slot (0-8) it goes into if that slot is free
  },

  pageSize: 20, // items per shop page
  centerNav: true, // SEARCH / NEXT / BACK in a centred row at the top of lists

  // Dropped stackable items near each other merge into one pile with a counter
  // (less lag). Items that don't stack are left alone.
  itemStacking: {
    enabled: true,
    radius: 4, // blocks
    showCount: true, // show "Bone x500" above piles
  },
};

